ALTER TABLE companies ADD COLUMN IF NOT EXISTS active boolean NOT NULL DEFAULT true;
ALTER TABLE users ADD CONSTRAINT users_company_id_unique UNIQUE(company_id,id);
ALTER TABLE customers ADD CONSTRAINT customers_company_id_unique UNIQUE(company_id,id);
ALTER TABLE orders ADD CONSTRAINT orders_company_id_unique UNIQUE(company_id,id);
ALTER TABLE orders ADD CONSTRAINT orders_customer_tenant_fk FOREIGN KEY(company_id,customer_id) REFERENCES customers(company_id,id) NOT VALID;
ALTER TABLE orders ADD CONSTRAINT orders_technician_tenant_fk FOREIGN KEY(company_id,technician_id) REFERENCES users(company_id,id) NOT VALID;
ALTER TABLE visits ADD CONSTRAINT visits_order_tenant_fk FOREIGN KEY(company_id,order_id) REFERENCES orders(company_id,id) NOT VALID;
ALTER TABLE visits ADD CONSTRAINT visits_technician_tenant_fk FOREIGN KEY(company_id,technician_id) REFERENCES users(company_id,id) NOT VALID;
ALTER TABLE reports ADD CONSTRAINT reports_order_tenant_fk FOREIGN KEY(company_id,order_id) REFERENCES orders(company_id,id) NOT VALID;
ALTER TABLE reports ADD CONSTRAINT reports_technician_tenant_fk FOREIGN KEY(company_id,technician_id) REFERENCES users(company_id,id) NOT VALID;
ALTER TABLE orders VALIDATE CONSTRAINT orders_customer_tenant_fk;
ALTER TABLE orders VALIDATE CONSTRAINT orders_technician_tenant_fk;
ALTER TABLE visits VALIDATE CONSTRAINT visits_order_tenant_fk;
ALTER TABLE visits VALIDATE CONSTRAINT visits_technician_tenant_fk;
ALTER TABLE reports VALIDATE CONSTRAINT reports_order_tenant_fk;
ALTER TABLE reports VALIDATE CONSTRAINT reports_technician_tenant_fk;
CREATE UNIQUE INDEX users_email_normalized_unique ON users(lower(trim(email)));
CREATE INDEX customers_company_created_idx ON customers(company_id,created_at DESC,id);
CREATE INDEX users_company_name_idx ON users(company_id,name,id);
CREATE INDEX orders_technician_idx ON orders(company_id,technician_id,created_at DESC,id);
CREATE TABLE sessions(id uuid PRIMARY KEY,company_id uuid NOT NULL,user_id uuid NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id));
CREATE INDEX sessions_user_idx ON sessions(company_id,user_id);
CREATE TABLE rate_buckets(key text PRIMARY KEY,hits integer NOT NULL,expires_at timestamptz NOT NULL);
CREATE INDEX rate_buckets_expiry_idx ON rate_buckets(expires_at);
CREATE TABLE audit_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,company_id uuid REFERENCES companies(id),actor_id uuid,action text NOT NULL,resource_id uuid,request_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_company_created_idx ON audit_events(company_id,created_at DESC);
CREATE TABLE media(id uuid PRIMARY KEY,company_id uuid NOT NULL,order_id uuid NOT NULL,object_key text NOT NULL UNIQUE,mime_type text NOT NULL,size_bytes integer NOT NULL CHECK(size_bytes>0),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(company_id,order_id) REFERENCES orders(company_id,id),UNIQUE(company_id,order_id,id));
ALTER TABLE visits ADD COLUMN photo_id uuid;
ALTER TABLE visits ADD CONSTRAINT visits_media_tenant_fk FOREIGN KEY(company_id,order_id,photo_id) REFERENCES media(company_id,order_id,id);
CREATE TABLE report_media(company_id uuid NOT NULL,order_id uuid NOT NULL,report_id uuid NOT NULL REFERENCES reports(id),media_id uuid NOT NULL,PRIMARY KEY(report_id,media_id),FOREIGN KEY(company_id,order_id,media_id) REFERENCES media(company_id,order_id,id));
ALTER TABLE reports ADD CONSTRAINT reports_company_order_unique UNIQUE(company_id,order_id,id);
ALTER TABLE report_media ADD CONSTRAINT report_media_report_tenant_fk FOREIGN KEY(company_id,order_id,report_id) REFERENCES reports(company_id,order_id,id);
CREATE TABLE idempotency_keys(company_id uuid NOT NULL,user_id uuid NOT NULL,key uuid NOT NULL,route text NOT NULL,body_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,user_id,key),FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id));
CREATE TABLE marketing_leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text NOT NULL,company text NOT NULL,phone text,team_size text NOT NULL,message text,consent boolean NOT NULL CHECK(consent),created_at timestamptz NOT NULL DEFAULT now());

ALTER TABLE orders ADD COLUMN cancellation_reason text;
ALTER TABLE visits ALTER COLUMN created_at SET DEFAULT clock_timestamp();
